// The Unicode classes the Metis text stack depends on. The tables come from Python's unicodedata
// (engine/text/unicode_tables.inc, generated by tools/text/gen_unicode.py).
#pragma once

#include <cstdint>

namespace lx::text::uni {

bool is_letter(uint32_t cp);       // \p{L}
bool is_number(uint32_t cp);       // \p{N}
bool is_regex_space(uint32_t cp);  // \s: the White_Space property
bool is_py_space(uint32_t cp);     // str.isspace(): the characters str.strip() removes
int decimal_digit(uint32_t cp);    // value of a Nd digit (int() and float() read these), else -1

}  // namespace lx::text::uni
